public class InnerHarnessHarnessHookTargetFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget>
{

    internal InnerHarnessHarnessHookSnsTargetFactory SnsFactory { get; set; }

    internal InnerHarnessHarnessHookLambdaTargetFactory LambdaFactory { get; set; }

    internal InnerHarnessHarnessHookEventBridgeTargetFactory EventBridgeFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget Create()
    {
        var harnessHookTargetResult = CreateHarnessHookTarget();
        factoryAction?.Invoke(harnessHookTargetResult);

        return harnessHookTargetResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget CreateHarnessHookTarget()
    {
        var harnessHookTargetResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget();

        return harnessHookTargetResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessHookTarget result)
    {
        base.CreateChildren(result);

        result.Sns ??= SnsFactory?.Build();
        result.Lambda ??= LambdaFactory?.Build();
        result.EventBridge ??= EventBridgeFactory?.Build();
    }

} // End Of Class

